## 🟡 5️⃣ SG90 Servo Motor Control (with ThingSpeak)

```cpp
#include <ESP8266WiFi.h>
#include <ThingSpeak.h>
#include <Servo.h>

const char* ssid = "MaharshiJD";
const char* pass = "#include<iostream.h>";
unsigned long channel = 3147692;
const char* api = "W5V2C1XYY3HJS7OZ";

WiFiClient client;
Servo servoMotor;

#define SERVO_PIN D3   // Connect SG90 signal wire here

void setup() {
  Serial.begin(115200);
  servoMotor.attach(SERVO_PIN);

  Serial.print("Connecting to WiFi");
  WiFi.begin(ssid, pass);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.println("\nConnected to WiFi!");
  ThingSpeak.begin(client);
}

void loop() {
  // Example: Rotate servo from 0° to 180° and back
  for (int angle = 0; angle <= 180; angle += 30) {
    servoMotor.write(angle);
    Serial.printf("Servo Angle: %d°\n", angle);

    ThingSpeak.setField(6, angle);  // Field 6 for servo angle
    ThingSpeak.writeFields(channel, api);

    delay(2000);
  }

  for (int angle = 180; angle >= 0; angle -= 30) {
    servoMotor.write(angle);
    Serial.printf("Servo Angle: %d°\n", angle);

    ThingSpeak.setField(6, angle);
    ThingSpeak.writeFields(channel, api);

    delay(2000);
  }
}
```

